/**
 * 负责诡术师原体绑定、夜换位选择和最终放逐替换。输入为原参与者、日期和配对，输出为原映射及终结结果。
 * 状态校验、初始化、历史追加和身份编码归本族槽；本 frame 保原 state 引用、expectedState 与唯一夜窗口。
 * history 先追加、expectedState 后刷新、pair／committed 最后更新；失败不退款或改写已消费号码。
 * finished 保留当日放逐映射，exileResolved 限一次输出；关闭／中止不把旧映射授给新生命或新原体。
 */
import type { TricksterReadState } from "@ai-werewolf-arena/game-contract";
import { mapTricksterExileTarget } from "./exile_mapping";
import { types } from "node:util";
import { COMPONENT, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import {
  getTricksterState,
  projectTricksterState,
  TRICKSTER_ROLE,
  nextTricksterChoice,
  TRICKSTER_STATE_SLOT,
} from "./state-slot";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  finished: boolean;
  exileResolved: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: TricksterReadState;
  /** 同引用状态的运行 JSON 检查点，不是第二份库存、档案验证或行动许可。 */
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // 已付换位保留原一次普通死亡效果；复活、换生命或原数据字段变访问器仍按原校验撤权。
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("trickster_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("trickster_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getTricksterState(actor.role) !== b.state || TRICKSTER_STATE_SLOT.checkpoint.identity(actor.role) !== b.expectedState)
    throw new Error("trickster_original_state_revoked");
  return b;
}
export function installTricksterBoard(world: World): void {
  if (boards.has(world)) throw new Error("trickster_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: TricksterReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("trickster_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("trickster_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("trickster_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("trickster_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === TRICKSTER_ROLE) {
      if (actorId !== null) throw new Error("trickster_original_roster_invalid");
      actorId = id;
      state = getTricksterState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("trickster_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: TRICKSTER_STATE_SLOT.checkpoint.identity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isTricksterBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}

export function beginTricksterNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.finished || day !== b.night.day + 1))
  )
    throw new Error("trickster_night_invalid");
  if (b.night) b.night.closed = true;
  const used = new Set(
    projectTricksterState(b.players.get(b.actorId)!.role)!.history.flatMap((row) => row.pair ?? []),
  );
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible = b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = {
    day,
    closed: false,
    committed: !eligible,
    finished: false,
    exileResolved: false,
    pair: null,
    targets,
  };
  return eligible ? b.actorId : null;
}
export function tricksterChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function tricksterMayPass(world: World, day: number): boolean {
  const b = requireBoard(world),
    last = b.state.history.at(-1);
  return !(last?.pair === null && last.day === day - 1);
}
export function tricksterChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}
export function commitTricksterExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || !tricksterChoicePending(world, actorId, day))
    throw new Error("trickster_choice_scope_invalid");
  const next = nextTricksterChoice(
    b.players.get(actorId)!.role,
    day,
    pair,
    tricksterChoiceTargets(world, day),
  );
  const choice = next.history.at(-1)!;
  TRICKSTER_STATE_SLOT.allowedWrites.appendHistory(() => b.state, choice);
  b.expectedState = TRICKSTER_STATE_SLOT.checkpoint.identity(b.players.get(actorId)!.role);
  n.pair = choice.pair && Object.freeze([choice.pair[0], choice.pair[1]] as [number, number]);
  n.committed = true;
}
export function cancelTricksterExchange(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed || n.finished)
    throw new Error("trickster_night_unsettled");
  n.pair = null;
}
export function finishTricksterNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed || n.finished)
    throw new Error("trickster_night_unsettled");
  n.finished = true;
}
export function resolveTricksterExile(
  world: World,
  day: number,
  requestedId: number,
): { requestedId: number; effectiveId: number; missed: boolean } {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed || !n.finished || n.exileResolved)
    throw new Error("trickster_exile_unsettled");
  const original = b.players.get(requestedId);
  if (!original?.life.alive) throw new Error("trickster_target_invalid");
  const effectiveId = mapTricksterExileTarget(requestedId, n.pair)!;
  const effective = b.players.get(effectiveId);
  if (!effective) throw new Error("trickster_target_invalid");
  n.exileResolved = true;
  return { requestedId, effectiveId, missed: !effective.life.alive };
}
export function assertTricksterRosterCurrent(world: World): void {
  requireBoard(world);
}
export function abortTricksterNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n && !n.finished) n.closed = true;
}

export function tricksterActorId(world: World): number {
  return requireBoard(world).actorId;
}

export function tricksterPackReady(world: World): boolean {
  return requireBoard(world).state.history.length > 0;
}

import { types } from "node:util";
export type ExchangePair = readonly [number, number];
function normalized(pair: ExchangePair | null): [number, number] | null {
  if (pair === null) return null;
  if (types.isProxy(pair) || !Array.isArray(pair)) throw new Error("trickster_pair_invalid");
  const d = Object.getOwnPropertyDescriptors(pair as object);
  const a = d["0"]?.value,
    b = d["1"]?.value;
  if (
    Reflect.ownKeys(d).length !== 3 ||
    d.length?.value !== 2 ||
    !Number.isSafeInteger(a) ||
    !Number.isSafeInteger(b) ||
    a <= 0 ||
    b <= 0 ||
    a >= Number.MAX_SAFE_INTEGER ||
    b >= Number.MAX_SAFE_INTEGER ||
    a === b
  )
    throw new Error("trickster_pair_invalid");
  return a < b ? [a, b] : [b, a];
}
export function matchingExchangePairs(a: ExchangePair | null, b: ExchangePair | null): boolean {
  const x = normalized(a),
    y = normalized(b);
  return !!x && !!y && x[0] === y[0] && x[1] === y[1];
}
/** Only final exile output is mapped; this never edits identities, seats or ballots. */
export function mapTricksterExileTarget(
  requested: number | null,
  pair: ExchangePair | null,
  magicianPair: ExchangePair | null = null,
): number | null {
  if (
    requested !== null &&
    (!Number.isSafeInteger(requested) || requested <= 0 || requested >= Number.MAX_SAFE_INTEGER)
  )
    throw new Error("trickster_target_invalid");
  const p = normalized(pair),
    cancelled = matchingExchangePairs(p, magicianPair);
  if (requested === null || !p || cancelled) return requested;
  return requested === p[0] ? p[1] : requested === p[1] ? p[0] : requested;
}

/**
 * 负责分发放逐、已提交整波与死亡动作的真实机制贡献。
 * 输入为原 World、名单／原因、日期／阶段及角色动作上下文；输出保留免死替换或追加死亡提案。
 * 整波扩展在实际 Alive 提交后、梦记录／遗言前同步运行；分发器不标死、改阶段或回滚事实。
 */
import { AliveComponent } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  EntityId,
  GameEvent,
  type DeathSources,
  type DeathShotSelection,
  type Phase,
} from "../../core/domain/model";
import { getDefaultHookRegistry, HookRegistry } from "../mechanisms";
import { World } from "../../core/domain/world";
import {
  createCommittedDeathWaveContributions,
  type CommittedDeathWaveHook,
} from "../mechanisms/hooks/hook_registry";

/**
 * 放逐阶段处理结果。
 */
export type VotedOutResult = import("../mechanisms").VotedOutResult;

/**
 * 死亡钩子处理结果（含追加死亡）。
 */
export type DeathHookResult = import("../mechanisms").DeathHookResult;

/**
 * 角色钩子分发入口：
 * - onVotedOut: 处理翻牌免死或返回待死亡名单。
 * - onDeath: 返回追加死亡提案；DeathResolution 写入死亡状态。
 */
export class EventRegistry {
  // 此列表只装配必需的整波贡献，不让旧注入的放逐／晚死亡 hooks 替换野孩子榜样结算。
  // 列表持有原函数引用，不持有第二份角色状态或生命账本。
  private readonly committedDeathWaveHooks: readonly CommittedDeathWaveHook[] =
    createCommittedDeathWaveContributions();
  constructor(private readonly hookRegistry: HookRegistry = getDefaultHookRegistry()) {}

  /** 只消费已经提交的原整波，首异常原样传播；不合并到后面的异步枪／死亡钩子。 */
  onCommittedDeathWave(
    world: World,
    deadIds: readonly EntityId[],
    deathSources: DeathSources,
    day: number,
    phase: Phase,
    events: GameEvent[],
  ): void {
    for (const hook of this.committedDeathWaveHooks)
      hook(world, deadIds, deathSources, day, phase, events);
  }

  /**
   * 处理放逐资格和免死，不提前写死亡或处理死亡警徽。
   */
  onVotedOut(world: World, targetId: EntityId, events: GameEvent[]): VotedOutResult {
    const handled = this.hookRegistry.onVotedOut(world, targetId, events);
    if (handled) {
      return handled;
    }

    const roleComp = world.getComponent(targetId, COMPONENT.Role);
    const aliveComp = world.getComponent(targetId, COMPONENT.Alive);

    if (!roleComp || !aliveComp || !aliveComp.alive) {
      return { prevented: false, removed: [], reason: "invalid_target" };
    }

    return {
      prevented: false,
      removed: [targetId],
      reason: "normal_voted_out",
    };
  }

  async onDeath(
    world: World,
    deadIds: EntityId[],
    deathSources: DeathSources,
    chooseDeathShot: (actorId: EntityId, abilityId?: string) => Promise<DeathShotSelection>,
    events: GameEvent[],
    commitAdditionalDeaths?: (result: DeathHookResult) => void,
    context?: import("../mechanisms/hooks/hook_registry").DeathHookContext,
  ): Promise<DeathHookResult> {
    return this.hookRegistry.onDeath(
      world,
      deadIds,
      deathSources,
      chooseDeathShot,
      events,
      commitAdditionalDeaths,
      context,
    );
  }
}

/**
 * 负责秘密之身放逐免死、公开翻牌与必需活人发言的完整同步交接。
 * 输入为原运行对象的晚读查询和已映射目标；输出原行动请求以及是否已处理放逐，不输出 JSON 租约。
 * 身体付款先于公开事实和必需录制；失败保留已付／已发布前缀，不重试或回滚。原权威独占资源和许可。
 * 生成器仅在原 Provider 等待点交出请求；调用方负责原唯一 await，拒绝时必须 return 进入已打开的 finally。
 * 非本族或不触发路径同步结束，不增加等待；发言复验、提交和关闭仍按原顺序执行。
 */
import { Phase } from "../../../../core/domain/identity";
import type { ActionRequest, ToolCall } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type { World } from "../../../../core/domain/world";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { checkpointNobleBodyAuthority, consumeSecretBodyExile } from "./authority";
import {
  openNobleBodyRevealRequest,
  nobleBodyRequestScope,
  commitNobleBodyRevealSpeech,
  closeNobleBodyRequest,
} from "./requests";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";

/** 原对象的只读视图；getter 在原表达式位置读取，不缓存 World、日次、回调或工厂方法，也不授予许可。 */
export interface SecretBodyExileRevealQueries {
  readonly enabled: ReadonlyBoardConfig["nobleSecretBody"];
  readonly world: World;
  readonly events: GameEvent[];
  readonly requests: ActionRequestConstructionPort;
  readonly toolGateway: Pick<ToolGateway, "validateAndSanitize">;
  readonly day: number;
  readonly isCurrent: (() => boolean) | undefined;
}

/** false 表示继续普通放逐；true 表示已完成翻牌。暂停时仅交原请求，不能据请求副本代替当前 scope。 */
export function* revealSecretBodyExile(
  queries: SecretBodyExileRevealQueries,
  effectiveTarget: number,
): Generator<ActionRequest, boolean, ToolCall | null> {
  if (queries.enabled) {
    const owned = checkpointNobleBodyAuthority(queries.world, true);
    if (effectiveTarget === owned.bodyId && owned.body.body.kind === "intact") {
      // 先耗身，再发布与必需录制；这些失败仍处于打开发言 scope 之前。
      const receipt = consumeSecretBodyExile(queries.world, queries.day),
        payload = { policy: "awa_noble_secret_body_v1" as const, ...receipt };
      queries.events.push({ timestamp: Date.now(), type: "secret_body_revealed", payload });
      getSessionRecorder()?.recordRequiredLogicOp({
        scope: "resolution",
        op: "secret_body_revealed",
        actorId: receipt.actorId,
        phase: Phase.Voting,
        status: "ok",
        output: payload,
      });
      const request = queries.requests.create({
          actorId: receipt.actorId,
          phase: Phase.Voting,
          allowedTools: ["speak"],
          stage: "awakened_idiot_reveal_speech",
          requiresAction: true,
          summary: { key: "request.summary.secret_body_reveal" },
          context: { allow_fallback: false, action_failure_policy: "error" },
        }),
        scope = openNobleBodyRevealRequest(
          queries.world,
          queries.day,
          request,
          queries.isCurrent ?? (() => true),
        );
      try {
        // 这里只暂停，不调用 Provider；恢复后先复验原 scope，再校验和提交。
        const action = yield request;
        if (nobleBodyRequestScope(queries.world, request) !== scope || action?.name !== "speak")
          throw Error("secret_body_reveal_speech_required");
        const valid = queries.toolGateway.validateAndSanitize(queries.world, receipt.actorId, action, {
          phase: Phase.Voting,
          day: queries.day,
          deferOperation: true,
        });
        if (
          !valid.ok ||
          !valid.sanitizedCall ||
          nobleBodyRequestScope(queries.world, request) !== scope
        )
          throw Error("secret_body_reveal_speech_required");
        const spoken = commitNobleBodyRevealSpeech(queries.world, scope, valid.sanitizedCall);
        queries.events.push({
          timestamp: Date.now(),
          type: "secret_body_reveal_speech",
          payload: { policy: "awa_noble_secret_body_v1", ...spoken },
        });
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId: receipt.actorId,
          phase: Phase.Voting,
          status: "ok",
          input: { tool: "speak", args: { text: spoken.text } },
        });
      } finally {
        // 成功／复验错误均关闭一次；Provider 拒绝由调用方 return 驱动这里，关闭错误沿原 finally 优先。
        closeNobleBodyRequest(scope);
      }
      return true;
    }
  }
  return false;
}

/**
 * 单元测试：验证诡术师独立 frame 契约。输入为原内存 owner、frame、reader 与受控非法修改；原字面断言、对象身份及拒绝结果为预期，不组装完整对局或模型传输。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  Role,
  Camp,
  WinCondition,
  COMPONENT,
  type RoleComponent,
  type AliveComponent,
} from "../../../../src/core";
import {
  createTricksterState,
  getTricksterState,
} from "../../../../src/game/mechanisms/roles/trickster/state-slot";
import {
  installTricksterBoard,
  beginTricksterNight,
  tricksterChoiceTargets,
  tricksterChoicePending,
  tricksterMayPass,
  commitTricksterExchange,
  cancelTricksterExchange,
  finishTricksterNight,
  resolveTricksterExile,
  abortTricksterNight,
} from "../../../../src/game/mechanisms/roles/trickster/night_frame";
function fixture() {
  const fixedRoles = [
    ...Array.from({ length: 4 }, () => Role.Wolf),
    ...Array.from({ length: 8 }, () => Role.Villager),
  ];
  const { world } = bootstrapGame(
    {
      boardSize: 12,
      hooks: { onDaybreak: false, onPreElection: false, onPreVote: false, onPerSpeechGap: false },
      enableSheriff: false,
      winConditions: [WinCondition.SlaughterSide],
      roleSetups: [
        { role: Role.Wolf, count: 4 },
        { role: Role.Villager, count: 8 },
      ],
    },
    { fixedRoles },
  );
  // Isolated frame fixture; production role registration is a later integration step.
  const role = world.getComponent(1, COMPONENT.Role)!;
  role.role = "trickster" as Role;
  (role as { privateState: Readonly<Record<string, unknown>> }).privateState = {
    trickster: createTricksterState(),
  };
  installTricksterBoard(world);
  return { world, role };
}
test("trickster frame maps final exile once after completed night", () => {
  const f = fixture();
  expect(beginTricksterNight(f.world, 1)).toBe(1);
  expect(tricksterChoicePending(f.world, 1, 1)).toBe(true);
  commitTricksterExchange(f.world, 1, 1, [2, 6]);
  expect(() => resolveTricksterExile(f.world, 1, 2)).toThrow("trickster_exile_unsettled");
  finishTricksterNight(f.world, 1);
  expect(resolveTricksterExile(f.world, 1, 2)).toEqual({
    requestedId: 2,
    effectiveId: 6,
    missed: false,
  });
  expect(() => resolveTricksterExile(f.world, 1, 2)).toThrow("trickster_exile_unsettled");
  expect(beginTricksterNight(f.world, 2)).toBe(1);
  expect(tricksterChoiceTargets(f.world, 2)).not.toContain(2);
  expect(tricksterChoiceTargets(f.world, 2)).not.toContain(6);
});
test("trickster frame keeps committed mapping after caster death", () => {
  const f = fixture();
  beginTricksterNight(f.world, 1);
  commitTricksterExchange(f.world, 1, 1, [2, 6]);
  f.world.getComponent(1, COMPONENT.Alive)!.alive = false;
  finishTricksterNight(f.world, 1);
  expect(resolveTricksterExile(f.world, 1, 2).effectiveId).toBe(6);
  expect(beginTricksterNight(f.world, 2)).toBeNull();
});
test("trickster mapped dead target yields no extra death rather than reverting", () => {
  const f = fixture();
  beginTricksterNight(f.world, 1);
  commitTricksterExchange(f.world, 1, 1, [2, 6]);
  f.world.getComponent(6, COMPONENT.Alive)!.alive = false;
  finishTricksterNight(f.world, 1);
  expect(resolveTricksterExile(f.world, 1, 2)).toEqual({
    requestedId: 2,
    effectiveId: 6,
    missed: true,
  });
  expect(f.world.getAliveEntityIds()).toContain(2);
});
test("trickster cancellation preserves consumed numbers", () => {
  const f = fixture();
  beginTricksterNight(f.world, 1);
  commitTricksterExchange(f.world, 1, 1, [2, 6]);
  cancelTricksterExchange(f.world, 1);
  finishTricksterNight(f.world, 1);
  expect(resolveTricksterExile(f.world, 1, 2).effectiveId).toBe(2);
  expect(getTricksterState(f.role)!.history).toEqual([{ day: 1, pair: [2, 6] }]);
  beginTricksterNight(f.world, 2);
  expect(tricksterChoiceTargets(f.world, 2)).not.toContain(2);
});
test("trickster rejects second voluntary pass and permits forced exhausted night", () => {
  const f = fixture();
  beginTricksterNight(f.world, 1);
  commitTricksterExchange(f.world, 1, 1, null);
  finishTricksterNight(f.world, 1);
  beginTricksterNight(f.world, 2);
  expect(tricksterMayPass(f.world, 2)).toBe(false);
  expect(() => commitTricksterExchange(f.world, 1, 2, null)).toThrow("trickster_consecutive_pass");
  commitTricksterExchange(f.world, 1, 2, [1, 2]);
  finishTricksterNight(f.world, 2);
  for (const id of f.world.entityIds())
    if (id !== 1) f.world.getComponent(id, COMPONENT.Alive)!.alive = false;
  expect(beginTricksterNight(f.world, 3)).toBeNull();
  finishTricksterNight(f.world, 3);
  expect(getTricksterState(f.role)!.history).toHaveLength(2);
});
test("trickster unfinished aborted night cannot yield an exile mapping", () => {
  const f = fixture();
  beginTricksterNight(f.world, 1);
  commitTricksterExchange(f.world, 1, 1, [2, 6]);
  abortTricksterNight(f.world);
  expect(() => resolveTricksterExile(f.world, 1, 2)).toThrow();
  expect(() => beginTricksterNight(f.world, 2)).toThrow();
});
test("trickster normal finally cleanup preserves finished day mapping", () => {
  const f = fixture();
  beginTricksterNight(f.world, 1);
  commitTricksterExchange(f.world, 1, 1, [2, 6]);
  finishTricksterNight(f.world, 1);
  abortTricksterNight(f.world);
  expect(resolveTricksterExile(f.world, 1, 2).effectiveId).toBe(6);
});
for (const kind of ["state", "role", "revival"] as const)
  test("trickster rejects revoked original " + kind, () => {
    const f = fixture();
    beginTricksterNight(f.world, 1);
    commitTricksterExchange(f.world, 1, 1, [2, 6]);
    finishTricksterNight(f.world, 1);
    if (kind === "state")
      (f.role as { privateState: Readonly<Record<string, unknown>> }).privateState = {
        ...f.role.privateState,
      };
    if (kind === "role") f.role.camp = Camp.Good;
    if (kind === "revival") {
      const life = f.world.getComponent(6, COMPONENT.Alive)!;
      life.alive = false;
      life.alive = true;
    }
    expect(() => resolveTricksterExile(f.world, 1, 2)).toThrow("trickster_original_state_revoked");
  });
